package cn.mop.contactworker;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class ContactImportWorkerSettingsTest {
    Map<String,String> values(){return new HashMap<>(Map.of("MOP_CONTACT_IMPORT_WORKER_ENABLED","true","SPRING_DATASOURCE_URL","jdbc:postgresql://127.0.0.1:25432/mop_test","SPRING_DATASOURCE_USERNAME","mop_test_runtime","SPRING_DATASOURCE_PASSWORD","SYNTHETIC_UNIT_ONLY"));}
    ContactImportWorkerSettings read(Map<String,String> values){return ContactImportWorkerSettings.from(new String[]{"remote_test"},values::get);}
    @Test void explicitProjectSettingsNeedNoStorageOrOidcCredential(){var values=values();var settings=ContactImportWorkerSettings.from(new String[]{"remote_test"},key->{assertFalse(key.contains("S3")||key.contains("OSS")||key.contains("OIDC")||key.equals("OBJECT_STORAGE_ENABLED"));return values.get(key);});assertEquals(30000,settings.lease().toMillis());assertEquals("mop_test_runtime",settings.databaseUser());assertFalse(settings.toString().contains("SYNTHETIC_UNIT_ONLY"));assertFalse(settings.toString().contains("25432"));}
    @Test void fixtureMixedUnknownAndMissingProfilesFailClosed(){for(String[] profiles:new String[][]{null,{}, {"local_fixture"},{"remote_test","other"},{"production"}})assertThrows(IllegalStateException.class,()->ContactImportWorkerSettings.from(profiles,values()::get));}
    @Test void enabledFlagMustBeExactAndExplicit(){for(String value:Arrays.asList(null,"","false","TRUE"," true")){var v=values();if(value==null)v.remove("MOP_CONTACT_IMPORT_WORKER_ENABLED");else v.put("MOP_CONTACT_IMPORT_WORKER_ENABLED",value);assertThrows(IllegalStateException.class,()->read(v));}}
    @Test void otherWorkerFlagsCannotBeMixedIntoDedicatedEntrypoint(){for(String key:List.of("MOP_PHOTO_WORKER_ENABLED","MOP_ASSET_IMPORT_WORKER_ENABLED")){var v=values();v.put(key,"true");assertThrows(IllegalStateException.class,()->read(v));}}
    @Test void databaseDestinationCannotExpandToOtherHostSchemaOrOptions(){for(String url:List.of("jdbc:postgresql://localhost:25432/mop_test","jdbc:postgresql://remote.invalid:25432/mop_test","jdbc:postgresql://127.0.0.1:0/mop_test","jdbc:postgresql://127.0.0.1:65536/mop_test","jdbc:postgresql://127.0.0.1:25432/other","jdbc:postgresql://127.0.0.1:25432/mop_test?password=SYNTHETIC_UNIT_ONLY")){var v=values();v.put("SPRING_DATASOURCE_URL",url);var failure=assertThrows(IllegalStateException.class,()->read(v));assertFalse(failure.getMessage().contains("SYNTHETIC_UNIT_ONLY"));assertFalse(failure.getMessage().contains(url));}}
    @Test void elevatedRoleMissingPasswordAndBlankRequiredValuesRejected(){for(String key:List.of("SPRING_DATASOURCE_URL","SPRING_DATASOURCE_USERNAME","SPRING_DATASOURCE_PASSWORD")){var v=values();v.put(key," ");assertThrows(IllegalStateException.class,()->read(v));}var v=values();v.put("SPRING_DATASOURCE_USERNAME","mop_test_migrator");assertThrows(IllegalStateException.class,()->read(v));}
    @Test void leaseOverrideIsCanonicalBoundedTechnicalValue(){for(String value:List.of("0","999","3600001","01","1e3","1000 ","-1000","999999999999999999")){var v=values();v.put("MOP_CONTACT_IMPORT_LEASE_MILLIS",value);assertThrows(IllegalStateException.class,()->read(v));}for(String value:List.of("1000","3600000")){var v=values();v.put("MOP_CONTACT_IMPORT_LEASE_MILLIS",value);assertEquals(Long.parseLong(value),read(v).lease().toMillis());}}
}
